CREATE TABLE IF NOT EXISTS salesperson_stock_assignments (id UUID PRIMARY KEY DEFAULT uuid_generate_v4(),company_id UUID NOT NULL REFERENCES companies(id) ON DELETE CASCADE,user_id UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,warehouse_id UUID NOT NULL,assigned_by UUID NOT NULL REFERENCES users(id) ON DELETE RESTRICT,is_active BOOLEAN NOT NULL DEFAULT TRUE,created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),CONSTRAINT salesperson_stock_user_company_fk FOREIGN KEY(user_id,company_id) REFERENCES company_memberships(user_id,company_id) ON DELETE CASCADE,CONSTRAINT salesperson_stock_warehouse_company_fk FOREIGN KEY(warehouse_id,company_id) REFERENCES warehouses(id,company_id) ON DELETE RESTRICT,CONSTRAINT salesperson_stock_company_user_unique UNIQUE(company_id,user_id));
CREATE INDEX IF NOT EXISTS idx_salesperson_stock_active_user ON salesperson_stock_assignments(company_id,user_id) WHERE is_active=true;
CREATE UNIQUE INDEX IF NOT EXISTS uq_salesperson_stock_active_warehouse ON salesperson_stock_assignments(company_id,warehouse_id) WHERE is_active=true;
ALTER TABLE salesperson_stock_assignments ENABLE ROW LEVEL SECURITY;
INSERT INTO permissions(permission,description,category) VALUES('sales:stock-assign','Assign dedicated stock warehouses to salespeople','sales') ON CONFLICT(permission) DO NOTHING;
INSERT INTO role_permissions(role,permission_id) SELECT roles.role,p.id FROM permissions p CROSS JOIN (VALUES('owner'::user_role),('admin'::user_role),('manager'::user_role)) roles(role) WHERE p.permission='sales:stock-assign' ON CONFLICT(role,permission_id) DO NOTHING;